  const reaction = Math.tanh((act - inh*0.65 + wav*0.2 + (bg1+bg2)*0.3 + spiral + ripple + micro)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const voronoi = Math.sin(Math.floor(sx*0.08)*12.9898 + Math.floor(sy*0.08)*78.233 + t*0.5)*0.1;
  const blend = reaction*0.6 + cell*0.2 + voronoi*0.1 + micro*0.1;
  const v = blend*0.5+0.5;
  const edge = Math.abs(reaction);
  const glow = edge > 0.75 ? (edge - 0.75)*4 : 0;
  const lum = 0.75 + Math.sin(reaction*Math.PI)*0.2 + glow*0.15;
  const edgeBoost = edge > 0.65 ? 1.0 + (edge-0.65)*0.6 : 0.95 + edge*0.08;
  const pal = [
    [6,12,52],[12,45,85],[15,85,115],[18,130,130],[40,165,145],
    [120,185,120],[195,190,75],[215,155,65],[210,110,70],[185,70,75],
    [145,45,85],[95,25,70],[50,18,58],[6,12,52]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx - i;
  const gR = pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const gG = pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const gB = pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const highlight = glow * 40;
  return [
    Math.min(255, (gR*lum*edgeBoost + highlight*0.6)|0),
    Math.min(255, (gG*lum*edgeBoost + highlight*0.8)|0),
    Math.min(255, (gB*lum*edgeBoost + highlight*1.0)|0)
  ];
}
